    put(box, m * at({s * 3.2, -1.6, -0.1}) * rot({0, 0, 1}, s * 0.62) * sc3(5.8, 2.4, 0.16), kJetMetal);
    put(box, m * at({s * 0.9, -5.0, 1.3}) * rot({0, 1, 0}, s * 0.32) * sc3(0.12, 2.6, 2.4), kJetDark);
